#!/usr/bin/python3

def readln(): return tuple(map(int, input().split()))

x, t, a, b, da, db = readln()
for i in range(t):
    for j in range(t):
        if a - i * da + b - j * db == x:
            da = -1
            break
    if da == -1:
        break
print('YES' if da == -1 else 'NO')

