def gcd(a, b):
    c = a % b
    return gcd(b, c) if c else b

x, t, a, b, da, db = map(int, input().split())
if x == 0: print('YES')
else:
    if (a - x) % da == 0: print('YES')
    elif (b - x) % db == 0: print('YES')
    elif a + b - t * (da + db) > x: print('NO')
    else:
        n = a + b - x
        if n % gcd(a, b): print('NO')
        else:
            for i in range(1, t + 1):
                if (n - i * da) % db == 0:
                    n = -1
                    break
            print('YES' if n < 0 else 'NO')
